<?php
 namespace Upyun; use Upyun\Api\Rest; use GuzzleHttp\Client; use GuzzleHttp\Psr7; use GuzzleHttp; class Upyun { protected $config; public function __construct(Config $config) { $this->setConfig($config); } public function setConfig(Config $config) { $this->config = $config; return $this; } public function write($path, $content, $params = array(), $withAsyncProcess = false) { if (!$content) { throw new \Exception('write content can not be empty.'); } $upload = new Uploader($this->config); $response = $upload->upload($path, $content, $params, $withAsyncProcess); if ($withAsyncProcess) { return $response; } return Util::getHeaderParams($response->getHeaders()); } public function read($path, $saveHandler = null, $params = array()) { $req = new Rest($this->config); $response = $req->request('GET', $path) ->withHeaders($params) ->send(); $params = Util::getHeaderParams($response->getHeaders()); if (! isset($params['x-upyun-list-iter'])) { if (is_resource($saveHandler)) { Psr7\copy_to_stream($response->getBody(), Psr7\stream_for($saveHandler)); return true; } else { return $response->getBody()->getContents(); } } else { $files = Util::parseDir($response->getBody()->getContents()); return array('files' => $files, 'is_end' => $params['x-upyun-list-iter'] === 'g2gCZAAEbmV4dGQAA2VvZg', 'iter' => $params['x-upyun-list-iter']); } } public function has($path) { $req = new Rest($this->config); try { $req->request('HEAD', $path) ->send(); } catch (GuzzleHttp\Exception\BadResponseException $e) { $statusCode = $e->getResponse()->getStatusCode(); if ($statusCode === 404) { return false; } else { throw $e; } } return true; } public function info($path) { $req = new Rest($this->config); $response = $req->request('HEAD', $path) ->send(); return Util::getHeaderParams($response->getHeaders()); } public function delete($path, $async = false) { $req = new Rest($this->config); $req->request('DELETE', $path); if ($async) { $req->withHeader('x-upyun-async', 'true'); } $res = $req->send(); return $res->getStatusCode() === 200; } public function createDir($path) { $path = rtrim($path, '/') . '/'; $req = new Rest($this->config); $res = $req->request('POST', $path) ->withHeader('folder', 'true') ->send(); return $res->getStatusCode() === 200; } public function deleteDir($path) { return $this->delete($path); } public function usage($path = '/') { $path = rtrim($path, '/') . '/'; $req = new Rest($this->config); $response = $req->request('GET', $path . '?usage') ->send(); return $response->getBody()->getContents(); } public function purge($urls) { $urlString = $urls; if (is_array($urls)) { $urlString = implode("\n", $urls); } $client = new Client([ 'timeout' => $this->config->timeout ]); $response = $client->request('POST', Config::ED_PURGE, [ 'headers' => Signature::getPurgeSignHeader($this->config, $urlString), 'form_params' => ['purge' => $urlString] ]); $result = json_decode($response->getBody()->getContents(), true); return $result['invalid_domain_of_url']; } public function process($source, $tasks) { $video = new Api\Pretreat($this->config); return $video->process($source, $tasks); } public function queryProcessStatus($taskIds) { $video = new Api\Pretreat($this->config); return $video->query($taskIds, '/status/'); } public function queryProcessResult($taskIds) { $video = new Api\Pretreat($this->config); return $video->query($taskIds, '/result/'); } } 